 static int checks;
 static void Require(bool condition,string message){checks++;if(!condition)throw new Exception(message);}
 static int Main(){
  var state=new WindowPolicyState();state.Register("left");state.Register("right");string token,other;
  Require(!state.Acquire("missing","import",out token),"Unknown surfaces cannot own a modal chain");
