  Require(state.PanelOwner==null&&!state.Panel("right","launcher"),"Modal acquisition closes panels and blocks new ones");
  Require(!state.Acquire("right","export",out other),"Second monitor cannot start a conflicting file operation");
  Require(!state.Acquire("left","power",out other),"Same monitor cannot start a competing power confirmation");
