  Require(!state.External()&&state.Owns("left","import"),"Alt+Tab retains reversible import without granting a new lease");
  Require(state.Release("left",token)&&!state.Blocked,"Exact owner/token releases the chain");
  Require(!state.Release("left",token),"Duplicate release is rejected");
  Require(state.Acquire("right","power",out other),"Power confirmation acquires after import completes");
  Require(!state.SuspendSurface("left")&&state.Owns("right","power"),"Minimizing another monitor cannot revoke the visible owner's confirmation");
  Require(state.SuspendSurface("right")&&!state.Blocked,"Minimizing the initiating monitor revokes its power confirmation");
  Require(state.Acquire("right","power",out other),"Explicit power action can start a new chain after restore");
  Require(state.External()&&!state.Blocked,"Leaving application revokes uncommitted power confirmation");
  Require(!state.Release("right",other),"Revoked power token cannot be used after returning");
  Require(state.Acquire("left","export",out token),"Export can start independently after revoked power");
  int generation=state.Generation;state.Reset();Require(state.Generation==generation+1&&!state.Blocked&&state.PanelOwner==null,"Forced lifecycle reset clears invisible modality and advances generation");
  Require(!state.Release("left",token),"Late reset-generation completion cannot unlock a new chain");
  Require(state.Acquire("left","import",out other)&&other!=token,"New operation receives a fresh token");
  Require(!state.Release("left",token)&&state.Blocked,"Old operation cannot release current import");
  Require(!state.Unregister("right")&&state.Blocked,"Unrelated surface disposal retains initiating import");
  Require(state.Unregister("left")&&!state.Blocked,"Initiating surface disposal removes its modal lock");
  Require(!state.Acquire("left","import",out token),"Disposed surface cannot reopen a chain");
  state.Register("left");state.Register("right");Require(state.Acquire("left","shell",out token),"Native Shell chain can reserve registered initiating surface");
  Require(!state.Acquire("right","import",out other)&&!state.Panel("right","settings"),"Native Shell chain blocks competing monitor dialogs and panels");
  Require(!state.Acquire("left","export",out other),"Native Shell chain also blocks competing action on its initiating monitor");
  Require(!state.External()&&state.Owns("left","shell"),"External foreground does not release a still-running native Shell operation");
  Require(!state.SuspendSurface("left")&&state.Owns("left","shell"),"Suspend waits for actual native Shell completion instead of unlocking early");
  Require(!state.Release("right",token)&&state.Blocked,"Other monitor cannot release native Shell lease");
  Require(state.Release("left",token)&&!state.Blocked,"Native context result releases its exact chain");
  Require(state.Acquire("left","shell",out other)&&other!=token&&!state.Release("left",token),"Stale native Shell result cannot release a later context invocation");
  state.Reset(true);Require(state.Owns("left","shell"),"Forced UI reset waits for actual native Shell cancellation result");
  state.Unregister("left",true);Require(state.Owns("left","shell")&&!state.Acquire("right","import",out token),"Disposing initiating Surface cannot unlock a still-live Rename chain");
  Require(state.Release("left",other)&&!state.Blocked,"Actual native result can release lease after its Surface has been removed");
  Require(!state.Release("left",other),"Late duplicate native Shell result is rejected after confirmed cancellation");
  state.Register("left");Require(state.Panel("left","launcher"),"Replacement surface can explicitly open a fresh panel");
  state.External();Require(state.PanelOwner==null&&!state.Blocked,"External transition never restores hover state");
  int released=0;var scope=new WindowPolicyScope(()=>released++);scope.Dispose();scope.Dispose();Require(released==1,"Native scope releases only once even during nested disposal");
  var work=new Rectangle(-1920,0,1920,1040);Require(WindowPlacement.Clamp(new Rectangle(-1800,100,1000,700),work)==new Rectangle(-1800,100,1000,700),"Valid negative-coordinate monitor placement is unchanged");
  Require(WindowPlacement.Clamp(new Rectangle(2560,300,1600,900),work)==new Rectangle(-1600,140,1600,900),"Unplugged monitor window is constrained to remaining working area");
  Require(WindowPlacement.Clamp(new Rectangle(10,-50,3000,2000),new Rectangle(0,0,1280,720))==new Rectangle(0,0,1280,720),"Oversized window fits a smaller monitor without hidden controls");
  var focus=new WindowForegroundState();Require(!focus.Observe(10,false)&&!focus.Observe(10,false),"Existing foreground Opera is a baseline, not an immediate hover dismissal");
  Require(!focus.Observe(20,true),"Own popup activation remains within the interaction group");
  Require(focus.Observe(10,false),"Alt+Tab back to external Opera closes a previously owned session");
  Require(!focus.Observe(30,true),"WorkerW with actual Surface child focus qualifies as own input");
  Require(focus.Observe(30,false),"Win+D focus loss is detected even when WorkerW foreground HWND is unchanged");
  Require(!focus.Observe(30,false),"Unchanged external desktop does not repeatedly emit lifecycle resets");
  // Opening a browser from Telegram may show a HWND while Telegram retains
  // foreground. Admission must come from the visible window event, not focus.
  var browser=new Rectangle(100,80,1200,800);var canvas=new Rectangle(0,0,1600,900);
  Require(WindowAttentionRules.RelevantEvent(0x8002,0,0),"Visible browser SHOW is relevant even with unchanged foreground");
  Require(WindowAttentionRules.RelevantEvent(0x17,0,0),"Restoring an existing minimized browser is also relevant");
  Require(!WindowAttentionRules.ExplicitPanel("launcher"),"Delayed category hover cannot supersede browser SHOW as an explicit click");
  Require(WindowAttentionRules.ExplicitPanel("settings")&&WindowAttentionRules.ExplicitPanel("themes"),"Explicit settings and theme clicks retain latest-user-interaction priority");
  Require(!WindowAttentionRules.RelevantEvent(0x8000,0,0),"CREATE before visibility must not claim priority");
  Require(!WindowAttentionRules.RelevantEvent(0x8002,-4,0)&&!WindowAttentionRules.RelevantEvent(0x8002,0,1),"Child/accessibility content changes are not new windows");
  Require(!WindowAttentionRules.Superseded(3,3,110,true,100),"Browser SHOW after our previous activation may still request priority without foreground change");
  Require(WindowAttentionRules.Superseded(3,4,100,true,100),"Later own activation cancels queued browser SHOW even in the same clock tick");
  Require(WindowAttentionRules.Superseded(4,4,100,true,110),"Late-delivered SHOW from before our last click cannot lower the reactivated app");
  Require(!WindowAttentionRules.Superseded(4,4,10,true,0xfffffff0),"Timestamp comparison handles uptime counter wrap for newer external event");
  Require(WindowAttentionRules.Superseded(4,4,0xfffffff0,true,10),"A later own activation across uptime wrap still supersedes the old event");
  Require(WindowAttentionRules.Ordinary(0,0,"Chrome_WidgetWin_1",true,false,false,true,false,browser),"Visible browser top-level qualifies independently of process name");
  Require(!WindowAttentionRules.Ordinary(0,0,"Chrome_WidgetWin_1",false,false,false,true,false,browser),"Hidden browser cannot lower the app");
  Require(!WindowAttentionRules.Ordinary(0,0,"Chrome_WidgetWin_1",true,true,false,true,false,browser),"Minimized browser cannot lower the app");
  Require(!WindowAttentionRules.Ordinary(0,0,"Chrome_WidgetWin_1",true,false,true,true,false,browser),"Another virtual desktop is excluded");
  Require(!WindowAttentionRules.Ordinary(0x40000000,0,"Chrome_WidgetWin_1",true,false,false,true,false,browser)&&!WindowAttentionRules.Ordinary(0,0,"Chrome_WidgetWin_1",true,false,false,false,false,browser),"Child windows cannot claim top-level priority");
  Require(!WindowAttentionRules.Ordinary(0,0x80,"Toast",true,false,false,true,false,browser)&&!WindowAttentionRules.Ordinary(0,0x08000000,"Toast",true,false,false,true,false,browser),"Tool and nonactivating notifications are ignored");
  Require(!WindowAttentionRules.Ordinary(0,0,"#32768",true,false,false,true,false,browser)&&!WindowAttentionRules.Ordinary(0,0,"tooltips_class32",true,false,false,true,false,browser),"Native menus and tooltips are ignored");
  Require(!WindowAttentionRules.Ordinary(0,0,"WorkerW",true,false,false,true,false,browser),"Explorer desktop does not count as an external ordinary window");
  Require(!WindowAttentionRules.Ordinary(0,0,"#32770",true,false,false,true,true,browser),"Owned file and Shell dialogs remain in our modal chain");
  Require(WindowAttentionRules.Plan(false,true,false,false,true,false,canvas,browser)==WindowYield.BelowWindow,"Our overlapping window yields below a shown browser without activating it");
  Require(WindowAttentionRules.Plan(false,true,false,false,false,false,canvas,browser)==WindowYield.None,"Already lower canvas is never raised toward a new browser");
  Require(WindowAttentionRules.Plan(true,true,false,false,true,false,canvas,browser)==WindowYield.None,"Desktop child is never reordered against a foreign top-level");
  Require(WindowAttentionRules.Plan(false,true,false,false,true,false,canvas,new Rectangle(2000,0,1200,900))==WindowYield.None,"Window on a different monitor does not reorder our surface");
  Require(WindowAttentionRules.Plan(false,true,false,false,true,true,canvas,browser)==WindowYield.None,"External topmost must not promote our non-topmost window by insertion");
  Require(WindowAttentionRules.Plan(false,true,false,true,true,true,canvas,browser)==WindowYield.DemoteOnly,"Unexpected own topmost is cleared without adopting foreign topmost");
  Require(WindowAttentionRules.Plan(false,false,false,false,true,false,canvas,browser)==WindowYield.None&&WindowAttentionRules.Plan(false,true,true,false,true,false,canvas,browser)==WindowYield.None,"Hidden/minimized surface stays hidden");
  state.Register("left");state.Register("right");Require(state.Acquire("left","notifications",out token),"Notification consent owns the same global native chain");
  Require(!state.External()&&state.Owns("left","notifications"),"Windows consent foreground retains notification chain");
  state.Reset(true);Require(state.Owns("left","notifications"),"Forced lifecycle reset waits for native consent completion");
  state.Unregister("left",true);Require(state.Owns("left","notifications")&&!state.Acquire("right","import",out other),"Replaced source cannot unlock native consent before completion");
  Require(state.Release("left",token)&&!state.Blocked,"Exact native consent completion releases removed source chain");
  state.Register("left");Require(state.Panel("left","settings"),"Panel records authoritative native owner");
  Require(!state.ClosePanel("right","settings")&&!state.ClosePanel("left","themes")&&state.PanelKind=="settings","Foreign or stale close cannot erase active panel");
  Require(state.ClosePanel("left","settings")&&state.PanelOwner==null,"Explicit local close clears native panel blocker");
  Require(state.Panel("left","settings")&&state.Panel("left","themes")&&!state.ClosePanel("left","settings")&&state.PanelKind=="themes","Late replaced-panel close preserves new panel");state.ClosePanel("left","themes");
  var hub=new Dictionary<string,object>{{"type","desktop-hub-request"},{"requestId",Guid.NewGuid().ToString("D")},{"action","notifications-access"}};
  Require(DesktopHubPolicy.Request(hub),"Only narrow explicit notification access request accepted");hub["path"]="C:\\private";Require(!DesktopHubPolicy.Request(hub),"Hub bridge rejects arbitrary paths or executable payloads");hub.Remove("path");hub["requestId"]="bad";Require(!DesktopHubPolicy.Request(hub),"Hub bridge requires an exact request UUID");
  Require(DesktopHubPolicy.Allowed("window-preview-close",false,false,true,true,true),"Preview cancellation always allowed through lifecycle/modal barriers");
  Require(DesktopHubPolicy.Allowed("window-preview",true,true,false,false,false),"Visible available Paper source may preview");
  Require(!DesktopHubPolicy.Allowed("window-preview",false,true,false,false,false)&&!DesktopHubPolicy.Allowed("window-preview",true,false,false,false,false),"Classic and hidden surfaces cannot use native hub");
  Require(!DesktopHubPolicy.Allowed("window-activate",true,true,true,false,false)&&!DesktopHubPolicy.Allowed("window-activate",true,true,false,true,false)&&!DesktopHubPolicy.Allowed("window-activate",true,true,false,false,true),"Native activation blocked by session, modal and authoritative panel owner");
  hub["requestId"]=Guid.NewGuid().ToString("D");hub["action"]="notification-activate";hub["id"]="123:456";Require(DesktopHubPolicy.Request(hub),"Notification activation accepts an ID-only native request");hub["url"]="https://example.test";Require(!DesktopHubPolicy.Request(hub),"WebView cannot choose a notification target URL");hub.Remove("url");hub["arguments"]="action=reply";Require(!DesktopHubPolicy.Request(hub),"WebView cannot choose native activation arguments");
  Require(!DesktopHubPolicy.Allowed("notification-activate",true,true,false,true,false)&&!DesktopHubPolicy.Allowed("notification-activate",true,true,true,false,false),"Notification navigation respects modal and session barriers");
  hub.Remove("arguments");hub["action"]="notification-dismiss";Require(DesktopHubPolicy.Request(hub),"A separate close request accepts only the native ID");
  hub["all"]=true;Require(!DesktopHubPolicy.Request(hub),"A single close cannot request clearing every notification");hub.Remove("all");hub.Remove("id");Require(!DesktopHubPolicy.Request(hub),"Closing requires an explicit notification ID");
  Require(!DesktopHubPolicy.Allowed("notification-dismiss",true,true,false,true,false)&&!DesktopHubPolicy.Allowed("notification-dismiss",true,true,true,false,false)&&!DesktopHubPolicy.Allowed("notification-dismiss",false,true,false,false,false),"Closing respects modal, session, and Paper Green surface ownership");
  hub["action"]="window-close";hub["id"]=new string('a',32);Require(DesktopHubPolicy.Request(hub),"A window close has its own ID-only action");
  hub["pid"]=123;Require(!DesktopHubPolicy.Request(hub),"WebView cannot choose a process to terminate");hub.Remove("pid");hub["force"]=true;Require(!DesktopHubPolicy.Request(hub),"The window close action has no forced termination option");
  Require(!DesktopHubPolicy.Allowed("window-close",true,true,false,true,false)&&!DesktopHubPolicy.Allowed("window-close",true,true,true,false,false)&&!DesktopHubPolicy.Allowed("window-close",true,true,false,false,true),"Window close respects the shared modal/session/panel hierarchy");
  hub.Clear();hub["type"]="desktop-hub-request";hub["requestId"]=Guid.NewGuid().ToString("D");hub["action"]="start-menu";Require(DesktopHubPolicy.Request(hub),"Start menu uses one fixed argument-free system action");
  hub["command"]="arbitrary";Require(!DesktopHubPolicy.Request(hub),"Start menu cannot supply a shell command");hub.Remove("command");hub["id"]="foreign-window";Require(!DesktopHubPolicy.Request(hub),"Start menu cannot choose a foreign native window");
  Require(!DesktopHubPolicy.Allowed("start-menu",true,true,false,true,false)&&!DesktopHubPolicy.Allowed("start-menu",true,true,true,false,false)&&!DesktopHubPolicy.Allowed("start-menu",true,true,false,false,true),"Start respects authoritative modal/session/panel guards");
  Console.WriteLine("Window policy native assertions: "+checks);return 0;
 }
}
